package cli

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// tomcatSPDXSBOM is an SPDX JSON SBOM generated by syft from the image of
// https://github.com/anchore/grant/issues/217 (tomcat:9.0.98-jdk17), trimmed to five packages.
// fontconfig and libapr1t64 only have concluded licenses, see grant/concluded_licenses_test.go.
func tomcatSPDXSBOM(t *testing.T) string {
	t.Helper()
	return filepath.Join(repoRoot(t), "grant", "testdata", "tomcat-9.0.98-jdk17", "sbom.spdx.json")
}

func TestCheckCmdIgnoreConcludedLicenses(t *testing.T) {
	const policy = "allow:\n  - MIT\n  - Apache-2.0\n"
	const ignoreConcluded = policy + "ignore-concluded-licenses: true\n"
	sbom := tomcatSPDXSBOM(t)

	concludedIgnored := []expressionCase{
		{pkg: "catalina", wantDecision: "allow", wantLicenses: []string{"Apache-2.0"}},
		{pkg: "libexpat1", wantDecision: "allow", wantLicenses: []string{"MIT"}},
		{pkg: "openssl", wantDecision: "allow", wantLicenses: []string{}},
		{pkg: "fontconfig", wantDecision: "allow", wantLicenses: []string{}},
		{pkg: "libapr1t64", wantDecision: "allow", wantLicenses: []string{}},
	}

	t.Run("concluded licenses are judged by default", func(t *testing.T) {
		stdout, stderr, rc := runGrant(t, "", "-c", writeConfig(t, policy), "-o", "json", "check", sbom)
		assert.NotZero(t, rc)
		assertFindings(t, parseFindings(t, stdout, stderr), []expressionCase{
			{pkg: "catalina", wantDecision: "allow", wantLicenses: []string{"Apache-2.0"}},
			{pkg: "libexpat1", wantDecision: "allow", wantLicenses: []string{"MIT"}},
			{pkg: "openssl", wantDecision: "allow", wantLicenses: []string{}},
			{pkg: "fontconfig", wantDecision: "deny", wantLicenses: []string{"HPND-sell-variant"}},
			{pkg: "libapr1t64", wantDecision: "deny", wantLicenses: []string{"BSD-4-Clause-UC", "ISC", "Zlib"}},
		})
		assert.NotContains(t, stdout, "ignoreConcludedLicenses", "the report only names the option when it is set")
		assert.NotContains(t, stderr, "concluded")
	})

	t.Run("config", func(t *testing.T) {
		stdout, stderr, rc := runGrant(t, "", "-c", writeConfig(t, ignoreConcluded), "-o", "json", "check", sbom)
		assert.Zero(t, rc)
		assertFindings(t, parseFindings(t, stdout, stderr), concludedIgnored)
		assert.Contains(t, stdout, `"ignoreConcludedLicenses": true`)
		assert.Contains(t, stderr, "ignored 2 concluded licenses on 2 packages, 2 of which are left with no licenses")
	})

	t.Run("a package left without licenses is subject to require-license", func(t *testing.T) {
		stdout, stderr, rc := runGrant(t, "", "-c", writeConfig(t, ignoreConcluded+"require-license: true\n"), "-o", "json", "check", sbom)
		assert.NotZero(t, rc)
		assertFindings(t, parseFindings(t, stdout, stderr), []expressionCase{
			{pkg: "catalina", wantDecision: "allow"},
			{pkg: "fontconfig", wantDecision: "deny", wantLicenses: []string{}},
			{pkg: "libapr1t64", wantDecision: "deny", wantLicenses: []string{}},
		})
	})

	t.Run("table output", func(t *testing.T) {
		stdout, stderr, rc := runGrant(t, "", "-c", writeConfig(t, policy), "check", sbom)
		assert.NotZero(t, rc)
		assertInOutput("HPND-sell-variant")(t, stdout, stderr, rc)

		stdout, stderr, rc = runGrant(t, "", "-c", writeConfig(t, ignoreConcluded), "check", sbom)
		assert.Zero(t, rc)
		assertNotInOutput("HPND-sell-variant")(t, stdout, stderr, rc)
	})

	t.Run("stdin", func(t *testing.T) {
		content, err := os.ReadFile(sbom)
		require.NoError(t, err)
		findings, rc := findingsByName(t, string(content), ignoreConcluded)
		assert.Zero(t, rc)
		assertFindings(t, findings, concludedIgnored)
	})
}

func TestListCmdIgnoreConcludedLicenses(t *testing.T) {
	sbom := tomcatSPDXSBOM(t)

	stdout, stderr, rc := runGrant(t, "", "-c", emptyConfig(t), "-o", "json", "list", sbom)
	assert.Zero(t, rc)
	assertFindings(t, parseFindings(t, stdout, stderr), []expressionCase{
		{pkg: "libexpat1", wantDecision: "unevaluated", wantLicenses: []string{"MIT"}},
		{pkg: "fontconfig", wantDecision: "unevaluated", wantLicenses: []string{"HPND-sell-variant"}},
		{pkg: "libapr1t64", wantDecision: "unevaluated", wantLicenses: []string{"Apache-2.0", "BSD-4-Clause-UC", "ISC", "Zlib"}},
	})

	stdout, stderr, rc = runGrant(t, "", "-c", writeConfig(t, "ignore-concluded-licenses: true\n"), "-o", "json", "list", sbom)
	assert.Zero(t, rc)
	assertFindings(t, parseFindings(t, stdout, stderr), []expressionCase{
		{pkg: "libexpat1", wantDecision: "unevaluated", wantLicenses: []string{"MIT"}},
		{pkg: "fontconfig", wantDecision: "unevaluated", wantLicenses: []string{}},
		{pkg: "libapr1t64", wantDecision: "unevaluated", wantLicenses: []string{}},
	})
}

// a package can carry both a concluded and a declared license, which the tomcat SBOM has no example of
func TestCheckCmdIgnoreConcludedLicensesKeepsDeclared(t *testing.T) {
	sbom := spdxJSONSBOM(spdxJSONPackage("concluded-and-declared", "GPL-3.0-only", "MIT OR GPL-3.0-only") + "," +
		spdxJSONPackage("concluded-same-as-declared", "MIT", "MIT") + "," +
		spdxJSONPackage("declared-and", "NOASSERTION", "MIT AND GPL-3.0-only"))

	findings, rc := findingsByName(t, sbom, "allow:\n  - MIT\n")
	assert.NotZero(t, rc)
	assertFindings(t, findings, []expressionCase{
		{pkg: "concluded-and-declared", wantDecision: "deny", wantLicenses: []string{"GPL-3.0-only"}},
		{pkg: "concluded-same-as-declared", wantDecision: "allow", wantLicenses: []string{"MIT"}},
		{pkg: "declared-and", wantDecision: "deny", wantLicenses: []string{"GPL-3.0-only"}},
	})

	findings, rc = findingsByName(t, sbom, "allow:\n  - MIT\nignore-concluded-licenses: true\n")
	assert.NotZero(t, rc, "a declared license that is not allowed still denies")
	assertFindings(t, findings, []expressionCase{
		{pkg: "concluded-and-declared", wantDecision: "allow", wantLicenses: []string{"MIT", "GPL-3.0-only"}},
		// the declared entry of a license that is also concluded stays
		{pkg: "concluded-same-as-declared", wantDecision: "allow", wantLicenses: []string{"MIT"}},
		{pkg: "declared-and", wantDecision: "deny", wantLicenses: []string{"GPL-3.0-only"}},
	})
}

func TestConfigCmdListsIgnoreConcludedLicenses(t *testing.T) {
	stdout, stderr, rc := runGrant(t, "", "config")
	assert.Zero(t, rc)
	assertInOutput("ignore-concluded-licenses: false # When true, ignore concluded licenses and only consider declared licenses")(t, stdout, stderr, rc)
}
